cd /tmp/claude-0/-home-user-GoogleCalendarEventCreator/1716e096-4d44-5984-844e-5cf264c9fe80/scratchpad
cat > summarize.mjs << 'EOF'
import fs from 'fs';
const file = process.argv[2];
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
for (const line of lines) {
  let obj;
  try { obj = JSON.parse(line); } catch { continue; }
  const ts = obj.timestamp || '';
  if (obj.attachment) {
    // skip hook noise, but note hook failures
    if (obj.attachment.hookName && !/success/i.test(obj.attachment.hookName) ) {
      console.log(`[${ts}] HOOK ${obj.attachment.hookName}: ${(obj.attachment.content||'').slice(0,200)}`);
    }
    continue;
  }
  const msg = obj.message;
  if (!msg) continue;
  const role = msg.role;
  const content = msg.content;
  if (typeof content === 'string') {
    console.log(`[${ts}] ${role}: ${content.slice(0,300)}`);
    continue;
  }
  if (Array.isArray(content)) {
    for (const c of content) {
      if (c.type === 'text') {
        const t = c.text.trim();
        if (t) console.log(`[${ts}] ${role} TEXT: ${t.slice(0,300)}`);
      } else if (c.type === 'tool_use') {
        console.log(`[${ts}] ${role} TOOL_USE ${c.name}: ${JSON.stringify(c.input).slice(0,200)}`);
      } else if (c.type === 'tool_result') {
        const cc = c.content;
        let s = typeof cc === 'string' ? cc : JSON.stringify(cc);
        console.log(`[${ts}] ${role} TOOL_RESULT${c.is_error ? ' ERROR' : ''}: ${(s||'').slice(0,200)}`);
      }
    }
  }
}
EOF
